from pathlib import Path

session_path = Path('src/room-song-command-session.ts')
session = session_path.read_text()

field_old = """export class RoomSongCommandSession {\n  private pending: PendingRoomSongCommand | null = null;\n  // State/rate-only commands deliberately do not own position. Their first\n"""
field_new = """export class RoomSongCommandSession {\n  private pending: PendingRoomSongCommand | null = null;\n  // Expiry can be observed by status, telemetry, registration, or a newer\n  // command before the periodic server sweep runs. Preserve every terminal\n  // command until sweep explicitly consumes it so a read/gate cannot steal the\n  // broadcast timeout settlement from the room.\n  private readonly expiredPending: AcceptedRoomSongCommand[] = [];\n  // State/rate-only commands deliberately do not own position. Their first\n"""
assert session.count(field_old) == 1, 'RoomSongCommandSession field anchor drifted'
session = session.replace(field_old, field_new)

sweep_old = """  sweep(nowMs: number) {\n    const pending = this.pending ? this.publicCommand(this.pending) : null;\n    this.expire(nowMs);\n    return pending && this.pending === null ? pending : null;\n  }\n"""
sweep_new = """  sweep(nowMs: number) {\n    this.expire(nowMs);\n    return this.expiredPending.shift() ?? null;\n  }\n"""
assert session.count(sweep_old) == 1, 'RoomSongCommandSession sweep anchor drifted'
session = session.replace(sweep_old, sweep_new)

expire_old = """  private expire(nowMs: number) {\n    if (this.pending && nowMs - this.pending.issuedAtMs > COMMAND_TIMEOUT_MS) {\n      this.pending = null;\n      this.stableCompleteProofCommandId = null;\n      this.correctionDebtSeconds = 0;\n      this.observedTransitionMutations.clear();\n    }\n  }\n"""
expire_new = """  private expire(nowMs: number) {\n    if (this.pending && nowMs - this.pending.issuedAtMs > COMMAND_TIMEOUT_MS) {\n      const expired = this.publicCommand(this.pending);\n      this.pending = null;\n      this.stableCompleteProofCommandId = null;\n      this.correctionDebtSeconds = 0;\n      this.observedTransitionMutations.clear();\n      this.expiredPending.push(expired);\n    }\n  }\n"""
assert session.count(expire_old) == 1, 'RoomSongCommandSession expire anchor drifted'
session = session.replace(expire_old, expire_new)
session_path.write_text(session)

Path('test/room-song-command-timeout-settlement.test.ts').write_text("""import assert from 'node:assert/strict';\nimport test from 'node:test';\n\nimport { parseRoomSongCommand } from '../src/room-song-command.js';\nimport { RoomSongCommandSession } from '../src/room-song-command-session.js';\n\nconst A = { participantId: 'participant-a', transportId: 'playback-tab-a', generation: 1 };\nconst VIDEO = 'dQw4w9WgXcQ';\nconst AFTER_TIMEOUT_MS = 4_001;\n\nfunction command(commandId: string, expectedRevision: number, action: 'play' | 'pause') {\n  const parsed = parseRoomSongCommand({ commandId, expectedRevision, action });\n  assert.equal(parsed.ok, true);\n  if (!parsed.ok) throw new Error('invalid room song command fixture');\n  return parsed.request;\n}\n\nfunction room() {\n  return {\n    type: 'youtube-timeline-status',\n    videoId: VIDEO,\n    state: 2,\n    serverTime: 10,\n    youtubeTime: 10,\n    ageMs: 0,\n    playbackRate: 1,\n    playbackLeaderParticipantId: A.participantId,\n    playbackTransportId: A.transportId,\n    playbackGeneration: A.generation,\n    connected: true,\n    leaderConnected: true,\n    leaderFresh: true,\n    handoffState: 'idle',\n  };\n}\n\nfunction telemetry() {\n  return {\n    videoId: VIDEO,\n    state: 2,\n    currentTime: 10,\n    duration: 200,\n    playbackRate: 1,\n    bufferedFraction: 0.8,\n  };\n}\n\nfunction beginPending(\n  session: RoomSongCommandSession,\n  commandId: string,\n  expectedRevision: number,\n  nextRevision: number,\n  nowMs: number,\n  action: 'play' | 'pause' = 'play',\n) {\n  const result = session.begin(\n    command(commandId, expectedRevision, action),\n    A.participantId,\n    A,\n    A.participantId,\n    room(),\n    expectedRevision,\n    nextRevision,\n    nowMs,\n  );\n  assert.equal(result.ok, true);\n  return result;\n}\n\ntest('status projection cannot consume room-song timeout settlement', () => {\n  const session = new RoomSongCommandSession();\n  beginPending(session, 'command-timeout-status', 0, 1, 0);\n\n  const status = session.statusPayload(AFTER_TIMEOUT_MS);\n  assert.equal(status.pendingCommandId, null);\n\n  assert.equal(session.sweep(AFTER_TIMEOUT_MS)?.commandId, 'command-timeout-status');\n  assert.equal(session.sweep(AFTER_TIMEOUT_MS), null);\n});\n\ntest('telemetry and target lookup cannot consume room-song timeout settlement', () => {\n  const telemetrySession = new RoomSongCommandSession();\n  beginPending(telemetrySession, 'command-timeout-telemetry', 0, 1, 0);\n  assert.deepEqual(\n    telemetrySession.gateTelemetry(telemetry(), A, room(), AFTER_TIMEOUT_MS),\n    { ok: true },\n  );\n  assert.equal(\n    telemetrySession.sweep(AFTER_TIMEOUT_MS)?.commandId,\n    'command-timeout-telemetry',\n  );\n\n  const targetSession = new RoomSongCommandSession();\n  beginPending(targetSession, 'command-timeout-target', 0, 1, 0);\n  assert.equal(targetSession.pendingForTarget(A, AFTER_TIMEOUT_MS), null);\n  assert.equal(targetSession.sweep(AFTER_TIMEOUT_MS)?.commandId, 'command-timeout-target');\n});\n\ntest('a newer command cannot erase an older timeout awaiting settlement', () => {\n  const session = new RoomSongCommandSession();\n  beginPending(session, 'command-timeout-first', 0, 1, 0);\n\n  beginPending(session, 'command-timeout-second', 1, 2, AFTER_TIMEOUT_MS, 'pause');\n  assert.equal(session.statusPayload(AFTER_TIMEOUT_MS).pendingCommandId, 'command-timeout-second');\n\n  // Expire the second command through a read before sweep has drained the first.\n  assert.equal(session.statusPayload(AFTER_TIMEOUT_MS * 2).pendingCommandId, null);\n  assert.equal(session.sweep(AFTER_TIMEOUT_MS * 2)?.commandId, 'command-timeout-first');\n  assert.equal(session.sweep(AFTER_TIMEOUT_MS * 2)?.commandId, 'command-timeout-second');\n  assert.equal(session.sweep(AFTER_TIMEOUT_MS * 2), null);\n});\n""")
